            free(f);
            fclose(fp);
            return NULL;
        }
    }

    fclose(fp);
    return f;
}

double *poisson_read_boundary(const char *filename, int expected)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    double *vals = (double *)malloc(expected * sizeof(double));
    if (!vals) { fclose(fp); return NULL; }

    int count = 0;
    while (count < expected) {
        double v;
        if (fscanf(fp, "%lf", &v) != 1) break;
        vals[count++] = v;
    }

    fclose(fp);
    if (count != expected) { free(vals); return NULL; }
    return vals;
}

