#include "solvers.h"
#include "vector.h"
#include <stdlib.h>
#include <math.h>
#include <string.h>

static SolveResult *result_create(int n, int maxiter)
{
    if (maxiter < 0) maxiter = 0;
    SolveResult *res = (SolveResult *)calloc(1, sizeof(SolveResult));
    if (!res) return NULL;

    res->x = vec_create(n);
    res->history = (double *)malloc((maxiter + 1) * sizeof(double));
    if (!res->x || !res->history) {
        free(res->x);
        free(res->history);
        free(res);
        return NULL;
    }
    res->history_len = 0;
    return res;
}

SolveResult *cg_solve(const CSRMatrix *A, const double *b, const double *x0,
                      double tol, int maxiter, Precond *P)
{
    if (!A || !b || A->rows != A->cols) return NULL;
    int n = A->rows;
    if (maxiter < 0) maxiter = 0;

    SolveResult *res = result_create(n, maxiter);
    if (!res) return NULL;

    double *r = vec_create(n);
    double *z = vec_create(n);
    double *p = vec_create(n);
    double *Ap = vec_create(n);
    if (!r || !z || !p || !Ap) {
        free(r); free(z); free(p); free(Ap);
        solve_result_destroy(res);
        return NULL;
    }

    if (x0) vec_copy(x0, res->x, n); else vec_zero(res->x, n);

    csr_spmv(A, res->x, Ap);
    for (int i = 0; i < n; i++) r[i] = b[i] - Ap[i];

    double bnorm = vec_norm2(b, n);
    if (bnorm == 0.0) bnorm = 1.0;

    res->true_residual = vec_norm2(r, n);
    res->relres = res->true_residual / bnorm;
    res->history[0] = res->relres;
    res->history_len = 1;
    res->converged = (res->relres < tol) ? 1 : 0;
    res->iterations = 0;
    if (res->converged || maxiter == 0) {
        free(r); free(z); free(p); free(Ap);
        return res;
    }

    if (precond_apply(P, A, r, z) != 0) {
        free(r); free(z); free(p); free(Ap);
        return res;
    }
    vec_copy(z, p, n);
    double rz_old = vec_dot(r, z, n);

    for (int iter = 1; iter <= maxiter; iter++) {
        csr_spmv(A, p, Ap);
        double pAp = vec_dot(p, Ap, n);
        if (fabs(pAp) < 1e-30) break;

        double alpha = rz_old / pAp;
        vec_axpy(alpha, p, res->x, n);
        vec_axpy(-alpha, Ap, r, n);

        /* Recompute the true residual rather than relying on the recurrence. */
        csr_spmv(A, res->x, Ap);
        for (int i = 0; i < n; i++) r[i] = b[i] - Ap[i];

        res->true_residual = vec_norm2(r, n);
        res->relres = res->true_residual / bnorm;
        res->history[iter] = res->relres;
        res->history_len = iter + 1;
        res->iterations = iter;

        if (res->relres < tol) {
            res->converged = 1;
            break;
        }

        if (precond_apply(P, A, r, z) != 0) break;
        double rz_new = vec_dot(r, z, n);
        if (fabs(rz_old) < 1e-30) break;
        double beta = rz_new / rz_old;
        vec_scale(beta, p, n);
        vec_axpy(1.0, z, p, n);
        rz_old = rz_new;
    }

    free(r); free(z); free(p); free(Ap);
    return res;
}

static void apply_givens(double *a, double *b, double c, double s)
{
    double t = c * (*a) + s * (*b);
    *b = -s * (*a) + c * (*b);
    *a = t;
}

static int solve_hessenberg_ls(double *H, double *g, int m, int kdim, double *y)
{
    if (kdim <= 0) return -1;

    double *c = (double *)malloc(m * sizeof(double));
    double *s = (double *)malloc(m * sizeof(double));
    if (!c || !s) { free(c); free(s); return -1; }

    for (int i = 0; i < kdim; i++) {
        for (int k = 0; k < i; k++) {
            apply_givens(&H[k*m+i], &H[(k+1)*m+i], c[k], s[k]);
        }

        double a = H[i*m+i];
        double b = H[(i+1)*m+i];
        if (b == 0.0) {
            c[i] = 1.0;
            s[i] = 0.0;
        } else {
            double r = hypot(a, b);
            c[i] = a / r;
            s[i] = b / r;
        }
        apply_givens(&H[i*m+i], &H[(i+1)*m+i], c[i], s[i]);
        apply_givens(&g[i], &g[i+1], c[i], s[i]);

    }

    for (int i = kdim - 1; i >= 0; i--) {
        double sum = g[i];
        for (int j = i + 1; j < kdim; j++) sum -= H[i*m+j] * y[j];
        if (fabs(H[i*m+i]) < 1e-15) { free(c); free(s); return -1; }
        y[i] = sum / H[i*m+i];
    }

    free(c);
    free(s);
    return 0;
}

SolveResult *gmres_solve(const CSRMatrix *A, const double *b, const double *x0,
                           double tol, int maxiter, int m, Precond *P)
{
    if (!A || !b || A->rows != A->cols) return NULL;
    int n = A->rows;
    if (m <= 0) m = 30;
    if (maxiter < 0) maxiter = 0;

    SolveResult *res = result_create(n, maxiter);
    if (!res) return NULL;

    double *r = vec_create(n);
    double *z = vec_create(n);
    double *Ap = vec_create(n);
    double *Av = vec_create(n);
    double *w = vec_create(n);
    double *g = (double *)malloc((m + 1) * sizeof(double));
    double *y = (double *)malloc(m * sizeof(double));
    double *H = (double *)calloc((m + 1) * m, sizeof(double));
    double *V = (double *)malloc(n * (m + 1) * sizeof(double));

    if (!r || !z || !Ap || !Av || !w || !g || !y || !H || !V) {
        free(r); free(z); free(Ap); free(Av); free(w); free(g); free(y); free(H); free(V);
        solve_result_destroy(res);
        return NULL;
    }

    if (x0) vec_copy(x0, res->x, n); else vec_zero(res->x, n);

    csr_spmv(A, res->x, Ap);
    for (int i = 0; i < n; i++) r[i] = b[i] - Ap[i];

    double bnorm = vec_norm2(b, n);
    if (bnorm == 0.0) bnorm = 1.0;

    res->true_residual = vec_norm2(r, n);
    res->relres = res->true_residual / bnorm;
    res->history[0] = res->relres;
    res->history_len = 1;
    res->converged = (res->relres < tol) ? 1 : 0;
    res->iterations = 0;
    if (res->converged || maxiter == 0) {
        free(r); free(z); free(Ap); free(Av); free(w); free(g); free(y); free(H); free(V);
        return res;
    }

    for (int cycle = 1; cycle <= maxiter; cycle++) {
        if (precond_apply(P, A, r, z) != 0) break;
        double beta = vec_norm2(z, n);
        if (beta == 0.0) break;

        for (int i = 0; i < n; i++) V[i] = z[i] / beta;
        for (int i = 0; i <= m; i++) g[i] = 0.0;
        g[0] = beta;
        memset(H, 0, (m + 1) * m * sizeof(double));

        int kdim = 0;
        int fail = 0;
        for (int j = 0; j < m; j++) {
            csr_spmv(A, V + j * n, Av);
            if (precond_apply(P, A, Av, w) != 0) { fail = 1; break; }

            for (int i = 0; i <= j; i++) {
                double h = vec_dot(w, V + i * n, n);
                H[i*m+j] = h;
                vec_axpy(-h, V + i * n, w, n);
            }

            double hnorm = vec_norm2(w, n);
            H[(j+1)*m+j] = hnorm;
            kdim = j + 1;

            if (hnorm < 1e-14) break;

            for (int i = 0; i < n; i++) V[(j+1)*n+i] = w[i] / hnorm;
        }
        if (fail) break;
        if (kdim == 0) break;

        for (int i = 0; i < kdim; i++) y[i] = 0.0;
        if (solve_hessenberg_ls(H, g, m, kdim, y) != 0) break;

        for (int i = 0; i < kdim; i++) vec_axpy(y[i], V + i * n, res->x, n);

        csr_spmv(A, res->x, Ap);
        for (int i = 0; i < n; i++) r[i] = b[i] - Ap[i];

        res->true_residual = vec_norm2(r, n);
        res->relres = res->true_residual / bnorm;
        res->history[cycle] = res->relres;
        res->history_len = cycle + 1;
        res->iterations = cycle;

        if (res->relres < tol) {
            res->converged = 1;
            break;
        }
    }

    free(r); free(z); free(Ap); free(Av); free(w); free(g); free(y); free(H); free(V);
    return res;
}

void solve_result_destroy(SolveResult *res)
{
    if (!res) return;
    free(res->x);
    free(res->history);
    free(res);
}
