#include "heat.h"
#include "vector.h"
#include "sparse.h"
#include "solvers.h"
#include "precond.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdio.h>

static void add_coo(COOMatrix *coo, int *k, int r, int c, double v)
{
    coo->row[*k] = r;
    coo->col[*k] = c;
    coo->values[*k] = v;
    (*k)++;
}

static int is_dirichlet_node(int i, int j, int nx, int ny,
                            PoissonBC left, PoissonBC right,
                            PoissonBC bottom, PoissonBC top)
{
    if (i == 0 && left.type == POISSON_DIRICHLET) return 1;
    if (i == nx - 1 && right.type == POISSON_DIRICHLET) return 1;
    if (j == 0 && bottom.type == POISSON_DIRICHLET) return 1;
    if (j == ny - 1 && top.type == POISSON_DIRICHLET) return 1;
    return 0;
}

static double dirichlet_value(int i, int j, int nx, int ny,
                              double *left_vals, double *right_vals,
                              double *bottom_vals, double *top_vals,
                              PoissonBC left, PoissonBC right,
                              PoissonBC bottom, PoissonBC top)
{
    if (i == 0 && left.type == POISSON_DIRICHLET) return left_vals[j];
    if (i == nx - 1 && right.type == POISSON_DIRICHLET) return right_vals[j];
    if (j == 0 && bottom.type == POISSON_DIRICHLET) return bottom_vals[i];
    if (j == ny - 1 && top.type == POISSON_DIRICHLET) return top_vals[i];
    return 0.0;
}

/* Assemble stiffness matrix K (negative Laplacian) with Neumann one-sided
 * stencil where applicable.  Dirichlet rows use the standard stencil; they are
 * later replaced with identity rows in the time-stepping matrix.  The returned
 * flux vector contains the Neumann boundary flux contributions. */
static CSRMatrix *assemble_stiffness(int nx, int ny, double x0, double x1,
                                     double y0, double y1,
                                     PoissonBC left, PoissonBC right,
                                     PoissonBC bottom, PoissonBC top,
                                     double *left_vals, double *right_vals,
                                     double *bottom_vals, double *top_vals,
                                     double **flux_out)
{
    int n = nx * ny;
    COOMatrix *coo = coo_create(n, n, 5 * n);
    double *flux = vec_create(n);
    if (!coo || !flux) { coo_destroy(coo); free(flux); return NULL; }

    double hx = (x1 - x0) / (nx - 1);
    double hy = (y1 - y0) / (ny - 1);
    double hx2 = hx * hx;
    double hy2 = hy * hy;

    int k = 0;
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
            int idx = i * ny + j;
            int is_left = (i == 0);
            int is_right = (i == nx - 1);
            int is_bottom = (j == 0);
            int is_top = (j == ny - 1);

            double diag = 0.0;
            double c_im = 0.0, c_ip = 0.0, c_jm = 0.0, c_jp = 0.0;

            if (is_left && left.type == POISSON_NEUMANN) {
                diag += 2.0 / hx2;
                c_ip = -2.0 / hx2;
                flux[idx] += 2.0 * left_vals[j] / hx;
            } else if (is_right && right.type == POISSON_NEUMANN) {
                diag += 2.0 / hx2;
                c_im = -2.0 / hx2;
                flux[idx] += 2.0 * right_vals[j] / hx;
            } else if (!is_left && !is_right) {
                diag += 2.0 / hx2;
                c_im = -1.0 / hx2;
                c_ip = -1.0 / hx2;
            } else {
                /* Boundary node with Dirichlet or unspecified BC: use the
                 * standard interior stencil with the missing neighbour
                 * omitted. */
                diag += 2.0 / hx2;
                if (is_left) c_ip = -1.0 / hx2;
                if (is_right) c_im = -1.0 / hx2;
            }

            if (is_bottom && bottom.type == POISSON_NEUMANN) {
                diag += 2.0 / hy2;
                c_jp = -2.0 / hy2;
                flux[idx] += 2.0 * bottom_vals[i] / hy;
            } else if (is_top && top.type == POISSON_NEUMANN) {
                diag += 2.0 / hy2;
                c_jm = -2.0 / hy2;
                flux[idx] += 2.0 * top_vals[i] / hy;
            } else if (!is_bottom && !is_top) {
                diag += 2.0 / hy2;
                c_jm = -1.0 / hy2;
                c_jp = -1.0 / hy2;
            } else {
                diag += 2.0 / hy2;
                if (is_bottom) c_jp = -1.0 / hy2;
                if (is_top) c_jm = -1.0 / hy2;
            }

            add_coo(coo, &k, idx, idx, diag);
            if (i > 0 && c_im != 0.0) add_coo(coo, &k, idx, (i-1)*ny+j, c_im);
            if (i < nx-1 && c_ip != 0.0) add_coo(coo, &k, idx, (i+1)*ny+j, c_ip);
            if (j > 0 && c_jm != 0.0) add_coo(coo, &k, idx, i*ny+(j-1), c_jm);
            if (j < ny-1 && c_jp != 0.0) add_coo(coo, &k, idx, i*ny+(j+1), c_jp);
        }
    }

    coo->nnz = k;
    CSRMatrix *K = coo_to_csr(coo);
    coo_destroy(coo);
    if (!K) { free(flux); return NULL; }
    *flux_out = flux;
    return K;
}

/* Assemble the time-stepping system matrix I + factor*K with Dirichlet rows
 * replaced by identity. */
static CSRMatrix *assemble_system_matrix(int nx, int ny, double x0, double x1,
                                        double y0, double y1,
                                        PoissonBC left, PoissonBC right,
                                        PoissonBC bottom, PoissonBC top,
                                        double factor)
{
    int n = nx * ny;
    COOMatrix *coo = coo_create(n, n, 5 * n);
    if (!coo) return NULL;

    double hx = (x1 - x0) / (nx - 1);
    double hy = (y1 - y0) / (ny - 1);
    double hx2 = hx * hx;
    double hy2 = hy * hy;

    int k = 0;
    for (int i = 0; i < nx; i++) {
        for (int j = 0; j < ny; j++) {
            int idx = i * ny + j;
            int is_left = (i == 0);
            int is_right = (i == nx - 1);
            int is_bottom = (j == 0);
            int is_top = (j == ny - 1);

            if (is_dirichlet_node(i, j, nx, ny, left, right, bottom, top)) {
                add_coo(coo, &k, idx, idx, 1.0);
                continue;
            }

            double diag = 1.0;  /* identity contribution */
            double c_im = 0.0, c_ip = 0.0, c_jm = 0.0, c_jp = 0.0;

            if (is_left && left.type == POISSON_NEUMANN) {
                diag += factor * 2.0 / hx2;
                c_ip = factor * (-2.0 / hx2);
            } else if (is_right && right.type == POISSON_NEUMANN) {
                diag += factor * 2.0 / hx2;
                c_im = factor * (-2.0 / hx2);
            } else if (!is_left && !is_right) {
                diag += factor * 2.0 / hx2;
                c_im = factor * (-1.0 / hx2);
                c_ip = factor * (-1.0 / hx2);
            } else {
                diag += factor * 2.0 / hx2;
                if (is_left) c_ip = factor * (-1.0 / hx2);
                if (is_right) c_im = factor * (-1.0 / hx2);
            }

            if (is_bottom && bottom.type == POISSON_NEUMANN) {
                diag += factor * 2.0 / hy2;
                c_jp = factor * (-2.0 / hy2);
            } else if (is_top && top.type == POISSON_NEUMANN) {
                diag += factor * 2.0 / hy2;
                c_jm = factor * (-2.0 / hy2);
            } else if (!is_bottom && !is_top) {
                diag += factor * 2.0 / hy2;
                c_jm = factor * (-1.0 / hy2);
                c_jp = factor * (-1.0 / hy2);
            } else {
                diag += factor * 2.0 / hy2;
                if (is_bottom) c_jp = factor * (-1.0 / hy2);
                if (is_top) c_jm = factor * (-1.0 / hy2);
            }

            add_coo(coo, &k, idx, idx, diag);
            if (i > 0 && c_im != 0.0) add_coo(coo, &k, idx, (i-1)*ny+j, c_im);
            if (i < nx-1 && c_ip != 0.0) add_coo(coo, &k, idx, (i+1)*ny+j, c_ip);
            if (j > 0 && c_jm != 0.0) add_coo(coo, &k, idx, i*ny+(j-1), c_jm);
            if (j < ny-1 && c_jp != 0.0) add_coo(coo, &k, idx, i*ny+(j+1), c_jp);
        }
    }

    coo->nnz = k;
    CSRMatrix *A = coo_to_csr(coo);
    coo_destroy(coo);
    return A;
}

static int parse_source_list(const char *arg, char ***files_out, int *count_out)
{
    char *copy = strdup(arg);
    if (!copy) return -1;

    int count = 1;
    for (char *p = copy; *p; p++) if (*p == ',') count++;

    char **files = (char **)calloc(count, sizeof(char *));
    if (!files) { free(copy); return -1; }

    int idx = 0;
    char *tok = strtok(copy, ",");
    while (tok) {
        files[idx++] = strdup(tok);
        tok = strtok(NULL, ",");
    }
    free(copy);

    if (idx != count) {
        for (int i = 0; i < idx; i++) free(files[i]);
        free(files);
        return -1;
    }

    *files_out = files;
    *count_out = count;
    return 0;
}

static void free_source_list(char **files, int count)
{
    for (int i = 0; i < count; i++) free(files[i]);
    free(files);
}
