int heat_solve(int nx, int ny, double x0, double x1, double y0, double y1,
               double alpha, double dt, int nsteps, const char *scheme,
               const char *ic_file, const char *source_arg,
               PoissonBC left, PoissonBC right, PoissonBC bottom, PoissonBC top,
               const char *solver, const char *precond, double tol, int maxiter,
               int restart, double omega, const char *output)
{
    if (nx < 2 || ny < 2 || x1 <= x0 || y1 <= y0 || alpha <= 0.0 || dt <= 0.0 ||
        nsteps < 0 || !scheme || !ic_file || !source_arg || !solver ||
        !precond || !output) {
        return -1;
    }

    int is_cn = (strcmp(scheme, "crank-nicolson") == 0);
    int is_be = (strcmp(scheme, "backward-euler") == 0);
    if (!is_be && !is_cn) return -1;

    int n = nx * ny;

    double *u = poisson_read_source(ic_file, nx, ny);
    if (!u) return -1;

    char **source_files = NULL;
    int nsources = 0;
    if (parse_source_list(source_arg, &source_files, &nsources) != 0) {
        free(u);
        return -1;
    }
    if (nsources != 1 && nsources != nsteps + 1) {
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }

    double **sources = (double **)calloc(nsources, sizeof(double *));
    if (!sources) {
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }
    for (int i = 0; i < nsources; i++) {
        sources[i] = poisson_read_source(source_files[i], nx, ny);
        if (!sources[i]) {
            for (int j = 0; j < i; j++) free(sources[j]);
            free(sources);
            free_source_list(source_files, nsources);
            free(u);
            return -1;
        }
    }

    double *left_vals = poisson_read_boundary(left.file, ny);
    double *right_vals = poisson_read_boundary(right.file, ny);
    double *bottom_vals = poisson_read_boundary(bottom.file, nx);
    double *top_vals = poisson_read_boundary(top.file, nx);
    if (!left_vals || !right_vals || !bottom_vals || !top_vals) {
        free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
        for (int i = 0; i < nsources; i++) free(sources[i]);
        free(sources);
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }

    double *flux = NULL;
    CSRMatrix *Ktmp = assemble_stiffness(nx, ny, x0, x1, y0, y1, left, right,
                                         bottom, top, left_vals, right_vals,
                                         bottom_vals, top_vals, &flux);
    if (!Ktmp || !flux) {
        csr_destroy(Ktmp);
        free(flux);
        free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
        for (int i = 0; i < nsources; i++) free(sources[i]);
        free(sources);
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }
    csr_destroy(Ktmp);

    double factor = is_cn ? 0.5 * alpha * dt : alpha * dt;
    CSRMatrix *A_sys = assemble_system_matrix(nx, ny, x0, x1, y0, y1,
                                               left, right, bottom, top, factor);
    if (!A_sys) {
        free(flux);
        free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
        for (int i = 0; i < nsources; i++) free(sources[i]);
        free(sources);
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }

    CSRMatrix *A_rhs = NULL;
    if (is_cn) {
        A_rhs = assemble_system_matrix(nx, ny, x0, x1, y0, y1,
                                       left, right, bottom, top, -factor);
        if (!A_rhs) {
            csr_destroy(A_sys);
            free(flux);
            free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
            for (int i = 0; i < nsources; i++) free(sources[i]);
            free(sources);
            free_source_list(source_files, nsources);
            free(u);
            return -1;
        }
    }

    Precond *P = precond_create(A_sys, precond, omega);
    if (!P) {
        csr_destroy(A_rhs);
        csr_destroy(A_sys);
        free(flux);
        free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
        for (int i = 0; i < nsources; i++) free(sources[i]);
        free(sources);
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }

    double *u_new = vec_create(n);
    double *rhs = vec_create(n);
    double *tmp = vec_create(n);
    if (!u_new || !rhs || !tmp) {
        free(u_new); free(rhs); free(tmp);
        precond_destroy(P);
        csr_destroy(A_rhs);
        csr_destroy(A_sys);
        free(flux);
        free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
        for (int i = 0; i < nsources; i++) free(sources[i]);
        free(sources);
        free_source_list(source_files, nsources);
        free(u);
        return -1;
    }

    int solver_calls = 0;
    int converged_all = 1;
    double max_residual = 0.0;

    for (int step = 0; step < nsteps; step++) {
        const double *f_n = (nsources == 1) ? sources[0] : sources[step];
        const double *f_np1 = (nsources == 1) ? sources[0] : sources[step + 1];

        if (is_be) {
            for (int i = 0; i < n; i++) {
                rhs[i] = u[i] + dt * f_np1[i] + alpha * dt * flux[i];
            }
        } else {
            csr_spmv(A_rhs, u, tmp);
            for (int i = 0; i < n; i++) {
                rhs[i] = tmp[i] + 0.5 * dt * (f_n[i] + f_np1[i]) + alpha * dt * flux[i];
            }
        }

        for (int i = 0; i < nx; i++) {
            for (int j = 0; j < ny; j++) {
                if (is_dirichlet_node(i, j, nx, ny, left, right, bottom, top)) {
                    int idx = i * ny + j;
                    rhs[idx] = dirichlet_value(i, j, nx, ny, left_vals, right_vals,
                                                bottom_vals, top_vals, left, right,
                                                bottom, top);
                }
            }
        }

        SolveResult *res = NULL;
        if (strcmp(solver, "cg") == 0) {
            res = cg_solve(A_sys, rhs, u, tol, maxiter, P);
        } else if (strcmp(solver, "gmres") == 0) {
            res = gmres_solve(A_sys, rhs, u, tol, maxiter, restart, P);
        } else {
            converged_all = 0;
            vec_copy(u, u_new, n);
        }
        solver_calls++;

        if (res) {
            if (!res->converged) converged_all = 0;
            if (res->relres > max_residual) max_residual = res->relres;
            vec_copy(res->x, u_new, n);
            solve_result_destroy(res);
        } else {
            converged_all = 0;
            if (max_residual < 1.0e30) max_residual = 1.0e30;
            vec_copy(u, u_new, n);
        }

        double *swap = u;
        u = u_new;
        u_new = swap;
    }

    int rc = vec_write_mm_array(u, n, output);

    printf("timesteps: %d\n", nsteps);
    printf("final_time: %.15e\n", dt * (double)nsteps);
    printf("solver_calls: %d\n", solver_calls);
    printf("converged_all: %s\n", converged_all ? "yes" : "no");
    printf("max_residual: %.6e\n", max_residual);

    free(u_new); free(rhs); free(tmp);
    precond_destroy(P);
    csr_destroy(A_rhs);
    csr_destroy(A_sys);
    free(flux);
    free(left_vals); free(right_vals); free(bottom_vals); free(top_vals);
    for (int i = 0; i < nsources; i++) free(sources[i]);
    free(sources);
    free_source_list(source_files, nsources);
    free(u);
    return rc;
}
