    if (!nx_s || !ny_s || !x0_s || !x1_s || !y0_s || !y1_s || !alpha_s ||
        !dt_s || !nsteps_s || !scheme || !ic_file || !source_arg ||
        !bc_left_s || !bc_right_s || !bc_bottom_s || !bc_top_s ||
        !solver || !precond || !tol_s || !maxiter_s || !output) {
        fprintf(stderr, "Error: heat requires grid, domain, alpha, dt, nsteps, scheme, ic, source, boundary conditions, solver, precond, tol, maxiter, output\n");
        usage("numsim");
        return 1;
    }

    int nx = atoi(nx_s);
    int ny = atoi(ny_s);
    double x0 = atof(x0_s);
    double x1 = atof(x1_s);
    double y0 = atof(y0_s);
    double y1 = atof(y1_s);
    double alpha = atof(alpha_s);
    double dt = atof(dt_s);
    int nsteps = atoi(nsteps_s);
