int csr_is_symmetric(const CSRMatrix *A, double tol)
{
    if (A->rows != A->cols) return 0;
    for (int i = 0; i < A->rows; i++) {
        for (int k = A->row_ptr[i]; k < A->row_ptr[i+1]; k++) {
            int j = A->col_indices[k];
            int idx = csr_find_in_row(A, j, i);
            if (idx < 0) return 0;
            if (fabs(A->values[k] - A->values[idx]) > tol) return 0;
        }
    }
    return 1;
}

double *csr_diagonal(const CSRMatrix *A)
{
    int n = A->rows < A->cols ? A->rows : A->cols;
    double *diag = vec_create(n);
    if (!diag) return NULL;
    for (int i = 0; i < n; i++) {
        int idx = csr_find_in_row(A, i, i);
        diag[i] = (idx >= 0) ? A->values[idx] : 0.0;
    }
    return diag;
}

static int mm_parse_header(const char *line, int *is_array, int *is_symmetric)
{
    char buf[1024];
    strncpy(buf, line, sizeof(buf)-1);
    buf[sizeof(buf)-1] = '\0';

    char *tok = strtok(buf, " \t\r\n");
    if (!tok || strcmp(tok, "%%MatrixMarket") != 0) return -1;

    tok = strtok(NULL, " \t\r\n");
    if (!tok || strcmp(tok, "matrix") != 0) return -1;

    tok = strtok(NULL, " \t\r\n");
    if (!tok) return -1;
    if (strcmp(tok, "coordinate") == 0) *is_array = 0;
    else if (strcmp(tok, "array") == 0) *is_array = 1;
    else return -1;

    tok = strtok(NULL, " \t\r\n");
    if (!tok) return -1;
    if (strcmp(tok, "real") != 0 && strcmp(tok, "double") != 0) return -1;

    *is_symmetric = 0;
    tok = strtok(NULL, " \t\r\n");
    if (tok && strcmp(tok, "symmetric") == 0) *is_symmetric = 1;

    return 0;
}

static int read_non_comment_line(FILE *fp, char *buf, int bufsize)
{
    while (fgets(buf, bufsize, fp)) {
        char *s = buf;
        while (*s == ' ' || *s == '\t') s++;
        if (*s == '%' || *s == '\n' || *s == '\r' || *s == '\0') continue;
        return 0;
    }
    return -1;
}

CSRMatrix *csr_read_mm(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) return NULL;

    char line[1024];
    if (!fgets(line, sizeof(line), fp)) { fclose(fp); return NULL; }
    int is_array = 0, is_symmetric = 0;
    if (mm_parse_header(line, &is_array, &is_symmetric) != 0 || is_array) {
        fclose(fp);
        return NULL;
    }

    int rows, cols, nnz;
    if (read_non_comment_line(fp, line, sizeof(line)) != 0) { fclose(fp); return NULL; }
    if (sscanf(line, "%d %d %d", &rows, &cols, &nnz) != 3 || rows <= 0 || cols <= 0 || nnz < 0) {
        fclose(fp);
        return NULL;
    }

    int cap = is_symmetric ? 2 * nnz + 1 : nnz;
    if (cap < 1) cap = 1;
    COOMatrix *coo = coo_create(rows, cols, cap);
    if (!coo) { fclose(fp); return NULL; }

    int k = 0;
    while (k < coo->nnz && read_non_comment_line(fp, line, sizeof(line)) == 0) {
        int r, c;
        double v;
        if (sscanf(line, "%d %d %lf", &r, &c, &v) != 3) continue;
        if (r < 1 || r > rows || c < 1 || c > cols) continue;
        r--; c--;

        coo->row[k] = r;
        coo->col[k] = c;
        coo->values[k] = v;
        k++;

        if (is_symmetric && r != c) {
            coo->row[k] = c;
            coo->col[k] = r;
            coo->values[k] = v;
            k++;
        }
    }
    coo->nnz = k;

    CSRMatrix *A = coo_to_csr(coo);
    coo_destroy(coo);
    fclose(fp);
    return A;
}

int csr_write_mm(const CSRMatrix *A, const char *filename)
{
    FILE *fp = fopen(filename, "w");
    if (!fp) return -1;

    fprintf(fp, "%%%%MatrixMarket matrix coordinate real general\n");
    fprintf(fp, "%d %d %d\n", A->rows, A->cols, A->nnz);
    for (int i = 0; i < A->rows; i++) {
        for (int k = A->row_ptr[i]; k < A->row_ptr[i+1]; k++) {
            fprintf(fp, "%d %d %.15g\n", i+1, A->col_indices[k]+1, A->values[k]);
        }
    }
    fclose(fp);
    return 0;
}

